E('code',x=120,y=200,w=930,h=680,title='a2_hunt.py（核心，簡化）',size=19,cells=[dict(code=['def score(D, kids, classes, crit):','    I = gini if crit == "gini" else entropy','    w = sum(len(k)/n * I(counts(k)) for k in kids)','    delta = I(counts(D)) - w','    split_info = -sum(len(k)/n * log2(len(k)/n) ...)','    if crit == "gain_ratio": return delta / split_info','    return delta'],at=b),dict(code=['hunt(loan, ["HomeOwner","Marital","Income"],','     ["No","Yes"], ["Income"], "gain_ratio")'],at=c)])
